// 1) Save item(s) to Outlook
Office365Outlook.V4CalendarPostItem(
    LookUp(Office365Outlook.CalendarGetTables().value, DisplayName = "Calendar").Name,
    Concatenate(
        "578 EHRM Learning Lab - ",
        var_reservationScenario
    ),
    var_StartDateTime_central,
    var_EndDateTime_central,
    "Central Standard Time",
    {
        requiredAttendees: var_Attendees,
        optionalAttendees: var_Attendees,
        body: var_EmailBody,
        categories: varMeetCat,
        location: varSelectedDesk.CombinedLocationDetails_multilinePlainText,
