// BACKUP Patch — decoupled, guarantees core data is captured no matter
// what else succeeds or fails.
//
// SAME FIX as the SUBMIT button: IfError requires all branches to be the
// same type. Patch() returns a RECORD, Notify() returns a BOOLEAN, which
// causes "Expecting a record value instead." The error branch below is
// wrapped in a record literal so its type matches the Patch.
ForAll(
    CollectionRecurrence As recBk,
    ForAll(
        colSelectedDesks As deskBk,
        IfError(
            Patch(
                backupList_DeskReservations,
                Defaults(backupList_DeskReservations),
                {
                    Title: var_Attendees & " – " & var_MeetingCategory & " - " & var_reservationScenario & " (" & var_reservationRole & ")",
                    submitterName_text: varMyProfile.displayName,
                    submitterEmail_text: Lower(varMyProfile.mail),
                    studentName_text: varStudentProfile.displayName,
                    studentEmail_text: Lower(varStudentProfile.mail),
                    reservationRole_text: var_reservationRole,
                    reservationScenario_text: var_reservationScenario,
                    reservationStart_datetime: var_StartDateTime_central,
                    reservationEnd_datetime: var_EndDateTime_central,
                    Active_choice: {Value: Text("true")}
                }
            ),
            // Error branch returns a RECORD to match Patch's return type.
            {
                ID: -1,
                handled: Notify(
                    "Backup save failed for one record: " & FirstError.Message,
                    NotificationType.Error
                )
            }
        )
    )
);

// ———————————————————————————————————————————————————————————————
